import{_ as e,o as a,c as d,a3 as o}from"./chunks/framework.C6R8kWFE.js";const u=JSON.parse('{"title":"数据权限","description":"","frontmatter":{},"headers":[],"relativePath":"backend/data-permission.md","filePath":"backend/data-permission.md","lastUpdated":1791101145000}'),s={name:"backend/data-permission.md"};function n(c,t,r,i,l,p){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据权限" tabindex="-1">数据权限 <a class="header-anchor" href="#数据权限" aria-label="Permalink to &quot;数据权限&quot;">​</a></h1><p>权限码回答「<strong>能不能做</strong>这个操作」，数据权限回答「<strong>能对哪些行做</strong>」「<strong>能看到哪些字段</strong>」。两者是独立的维度——有权限码但查不到数据、能查到但某些列被打码，都是数据权限在起作用。</p><p>权限码本身见 <a href="./permission">权限管理</a>。</p><h2 id="两个维度" tabindex="-1">两个维度 <a class="header-anchor" href="#两个维度" aria-label="Permalink to &quot;两个维度&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次请求要过的门：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  权限码        能不能调这个接口          → 不过：403</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>  数据范围      能看到哪些行              → 不过：查不到（不是 403；目前只作用于用户列表）</span></span>
<span class="line"><span>     ↓</span></span>
<span class="line"><span>  字段级安全    能看哪些列、能改哪些列    → 不过：值被置空或被打码</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">「有权限但列表是空的」不是 bug</p><p>返回 <code>200</code> 且 <code>items</code> 为空、而不是 <code>403</code>——这是数据范围在起作用。排查方向是数据范围配置，不是权限码。</p></div><h2 id="数据范围-行级" tabindex="-1">数据范围（行级） <a class="header-anchor" href="#数据范围-行级" aria-label="Permalink to &quot;数据范围（行级）&quot;">​</a></h2><p>范围枚举是 <code>DataPermissionScope</code>：角色的档位写在 <code>SysRole.DataScope</code>；成员的覆盖写在成员关系 <code>SysTenantUser.DataScopeOverride</code>（null 表示跟随角色），同一个人在不同租户各自设置。</p><table tabindex="0"><thead><tr><th>范围</th><th>含义</th><th>依赖</th></tr></thead><tbody><tr><td><code>SelfOnly</code></td><td>仅本人数据</td><td>—</td></tr><tr><td><code>DepartmentOnly</code></td><td>本部门</td><td><code>SysUserDepartment</code> 的<strong>全部有效部门归属</strong></td></tr><tr><td><code>DepartmentAndChildren</code></td><td>本部门及下级</td><td>部门<strong>闭包表</strong></td></tr><tr><td><code>All</code></td><td>全部数据（仍受租户过滤器约束）</td><td>—</td></tr><tr><td><code>Custom</code></td><td>指定部门集合</td><td><code>Sys_Role_Data_Scope</code> / <code>Sys_User_Data_Scope</code></td></tr></tbody></table><p>解析入口是 <code>IUserDataScopeFilterService.ResolveAccessibleUsersAsync</code>，当前只由用户分页查询（<code>UserQueryService.GetUserPageAsync</code>）调用，用户导出复用这条查询；用户详情、选择项，以及其它资源的查询和写操作都不施加数据范围。数据范围是租户侧概念：平台没有部门与成员关系，不施加数据范围（超管只在平台成立，也就不需要单独豁免）。</p><h3 id="合并规则" tabindex="-1">合并规则 <a class="header-anchor" href="#合并规则" aria-label="Permalink to &quot;合并规则&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>成员有覆盖            →  只按覆盖；Custom 时取 Sys_User_Data_Scope 里本成员的部门</span></span>
<span class="line"><span>        否则</span></span>
<span class="line"><span>启用角色的数据范围    →  多角色取并集；任一角色为 All 即放行全部；</span></span>
<span class="line"><span>                         Custom 角色并入 Sys_Role_Data_Scope 的部门</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>一个部门都没命中      →  退回仅本人</span></span></code></pre></div><p>成员覆盖用于「这个人比较特殊」的场景（如 CEO 挂的是部门经理角色、但要看全部），不要拿它当常规手段——角色才是可维护的授权单位。</p><p>档位与部门一次设置：角色在角色页的「数据范围」、成员在用户页的「数据范围」，先选档位，自定义时在部门树里勾部门、逐项设「含下级」。被上级「含下级」覆盖的部门会给出提示。全局角色只在平台设档位、不能自定义；支持成员（平台人员入驻）同样由所在租户设置。</p><h3 id="依赖组织架构" tabindex="-1">依赖组织架构 <a class="header-anchor" href="#依赖组织架构" aria-label="Permalink to &quot;依赖组织架构&quot;">​</a></h3><p><code>DepartmentOnly</code> 与 <code>DepartmentAndChildren</code> 完全依赖 <a href="./organization">组织架构</a>：</p><ul><li><code>DepartmentOnly</code> 取用户在当前租户下<strong>全部状态有效的部门归属</strong>（<code>SysUserDepartment</code>，不区分 <code>IsMain</code>）；</li><li><code>DepartmentAndChildren</code> 在此基础上靠<strong>部门闭包表</strong>一次展开整棵子树。</li></ul><div class="danger custom-block"><p class="custom-block-title">闭包表失真 = 数据范围算错</p><p>闭包表是查询加速镜像，<strong>所有写入必须由 <code>SysDepartment</code> 变更触发</strong>。绕过服务层直改部门表会让闭包表失真，表现是某些下级部门的数据看不到、或看到了本不该看到的。</p><p>修复要重建该子树的闭包，不要手工补行。</p></div><h3 id="组织变更的连锁影响" tabindex="-1">组织变更的连锁影响 <a class="header-anchor" href="#组织变更的连锁影响" aria-label="Permalink to &quot;组织变更的连锁影响&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变更</th><th>影响</th></tr></thead><tbody><tr><td>移动部门</td><td>闭包表重建 → 该子树下所有人的 <code>DepartmentAndChildren</code> 范围变化</td></tr><tr><td>改用户部门归属</td><td>该用户的 <code>DepartmentOnly</code> / <code>DepartmentAndChildren</code> 范围变化</td></tr><tr><td>改角色数据范围</td><td>该角色下所有用户的可见范围变化</td></tr></tbody></table><p>数据范围每次请求实时从库解析，不进授权快照；角色写入路径会失效授权快照（<code>InvalidateAuthorizationAsync</code>），部门写入路径失效组织缓存（<code>InvalidateOrganizationAsync</code>）。</p><h2 id="字段级安全-列级" tabindex="-1">字段级安全（列级） <a class="header-anchor" href="#字段级安全-列级" aria-label="Permalink to &quot;字段级安全（列级）&quot;">​</a></h2><p><code>SysFieldLevelSecurity</code> 按「<strong>实体 × 字段 × 目标</strong>」定义规则：限制某个角色 / 用户 / 部门对某个实体某个字段的读取方式与修改能力。规则<strong>只收紧、不放宽</strong>——没有规则就是明文可改。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>targetType</code> / <code>targetId</code></td><td>目标：角色（当前用户生效且启用的角色）、用户（本人）、部门（该部门<strong>及其下级部门</strong>的有效成员；停用部门跳过但继续向上找）</td></tr><tr><td><code>entityName</code></td><td>实体类名，如 <code>SysUser</code>；只能从实体目录里选</td></tr><tr><td><code>fieldName</code></td><td>实体属性名，如 <code>Phone</code>（区分大小写）；只能从该实体的字段里选</td></tr><tr><td><code>maskStrategy</code></td><td>读取方式：明文、部分脱敏、哈希、全部星号、固定文本、隐藏</td></tr><tr><td><code>maskKeepHead</code> / <code>maskKeepTail</code></td><td>部分脱敏保留前几位、后几位（仅部分脱敏，0–32，不能都为 0）</td></tr><tr><td><code>maskReplacement</code></td><td>固定文本方式显示的文字（仅固定文本）</td></tr><tr><td><code>isEditable</code></td><td>能否修改。明文规则必须只读（否则什么都没限制）；脱敏且可编辑为「只写」：看不到原值，但能填新值覆盖（如更换密钥）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">实体目录</p><p>可配置的实体由各模块在服务注册里登记（<code>AddSaasFieldSecurityEntities</code>、<code>AddAIFieldSecurityEntities</code> 等，底层是 <code>FieldSecurityEntityOptions.Add&lt;TEntity&gt;()</code>）。实体显示名取表说明（<code>SugarTable.TableDescription</code>），字段显示名取列说明；主键、租户、并发版本、软删除等框架列不在字段列表里。配置页经 <code>FieldLevelSecurityQuery/FieldSecurityEntities</code> 取目录，实体与字段都是下拉选择，不手输。</p><p><strong>登记即承诺</strong>：该实体的查询服务要门控查询条件，应用服务新建、修改（含状态）前要做写校验，响应里要能认出它的 DTO。<code>FieldSecurityEntityWiringTests</code> 从各模块的登记方法取登记表，核对这几处都已落地（门控与写校验扫源码，DTO 看映射器），缺一处就失败；代码里按未登记的实体调用字段安全，运行时直接报错。</p></div><p>非文本字段只能「明文只读」或「隐藏」（隐藏后返回类型默认值）。同一字段命中多条规则时取<strong>最严</strong>的读取方式，严格程度按泄露的信息量排：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>明文 &lt; 部分脱敏（泄露片段）&lt; 哈希（泄露是否相等）&lt; 全部星号（泄露长度）&lt; 固定文本（只泄露有没有值）&lt; 隐藏</span></span></code></pre></div><p>部分脱敏多条时保留位数取最少；任一命中规则只读即只读。</p><p><strong>平台规则</strong>（<code>TenantId = 0</code>）对所有租户生效，只能在平台维护；租户看得见、改不了（列表里标「平台」）。全局角色与系统角色的规则同样只能在平台维护。</p><h3 id="脱敏在服务端完成" tabindex="-1">脱敏在服务端完成 <a class="header-anchor" href="#脱敏在服务端完成" aria-label="Permalink to &quot;脱敏在服务端完成&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">后端返回的就是打码后的值</p><p>如 <code>138****5678</code>。<strong>前端不做二次打码</strong>，绕过前端直接调接口也拿不到明文。</p></div><p>打码在<strong>输出边界</strong>统一做，不逐个接口接线：<code>FieldSecurityResponseFilter</code> 在每个接口返回前沿响应的对象图（集合、分页、聚合详情里嵌套的 DTO、字典的值）找出属于登记实体的 DTO，按该实体的规则就地打码。列表、详情、下拉选项、聚合详情（如用户编辑表单取的 <code>UserManagementDetail</code>）、新建与修改后回传的详情都经过这一道口子，新接口不会因为漏接而漏出明文。</p><ul><li><strong>DTO 属于哪个实体</strong>：由应用层映射器认定——<code>public static XxxDto ToXxx(SysEntity entity, …)</code> 即认定 <code>XxxDto</code> 属于 <code>SysEntity</code>（<code>IFieldSecurityDtoCatalog</code>）。所以 DTO 必须经映射器从实体生成；一个 DTO 由两个登记实体映射出来时启动即报错。</li><li><strong>改名的属性</strong>：DTO 属性与实体字段不同名时（如 <code>UserSessionId</code> → <code>SessionId</code>），在 DTO 属性上加 <code>[FieldSecuritySource(nameof(SysAccessLog.UserSessionId))]</code>，否则按名字打不到码；测试扫描映射器，未声明的改名直接失败。</li><li><strong>多来源 DTO</strong>：由多个实体映射出来的 DTO（如链路时间线 <code>TraceTimelineItemDto</code>）实现 <code>IFieldSecurityMultiSourceDto</code>，按每条自己的来源实体与字段对应打码。</li><li><strong>与响应缓存</strong>：过滤器排在框架缓存过滤器<strong>外层</strong>，缓存里存原值，每次命中按当次用户打码；<code>HybridCache</code> 对可变类型每次命中给新实例，就地打码不污染缓存。</li><li><strong>进程内直调</strong>不经过 HTTP 过滤器：导出任务按发起人身份调用查询服务，导出基类每取一页先 <code>MaskAsync</code> 再写出，导出文件与在线列表同一口径。进程内的业务逻辑直调查询服务拿到的是原值（需要真实值做计算）。</li></ul><p>读全局数据要切到平台上下文的查询（打印模板、编号规则），查询门控放在切换<strong>之外</strong>：字段规则按请求方在所属租户的角色、部门判定；打码在响应过滤器里做，本就在请求方上下文。</p><h3 id="查询条件也受门控" tabindex="-1">查询条件也受门控 <a class="header-anchor" href="#查询条件也受门控" aria-label="Permalink to &quot;查询条件也受门控&quot;">​</a></h3><p>构建完查询条件后调用 <code>_fieldSecurity.GuardQueryAsync(request.Conditions, typeof(SysUser), ct)</code>，剔除<strong>读受保护字段</strong>（非明文）上的排序、过滤与关键字搜索字段——否则可按结果顺序或筛选命中反推原值。字段名大小写不敏感（前端列键多为 camelCase）。</p><div class="warning custom-block"><p class="custom-block-title">强制约束放在门控之后</p><p>数据范围、超管隐藏、租户边界这类服务端强制条件，一律在 <code>GuardQueryAsync</code> <strong>之后</strong>追加；否则有人把相关字段设成受保护，强制条件会被一起剔掉。</p></div><div class="warning custom-block"><p class="custom-block-title">「排序点了没反应」优先查字段安全</p><p>被剔掉时后端<strong>不会报错</strong>，只是安静地不生效。「按某字段搜索没效果」也可能是这个原因。</p></div><h3 id="写校验" tabindex="-1">写校验 <a class="header-anchor" href="#写校验" aria-label="Permalink to &quot;写校验&quot;">​</a></h3><p>应用服务新建前调用 <code>EnsureCreatableAsync(typeof(X), input, ct)</code>，修改与改状态前调用 <code>EnsureUpdatableAsync(typeof(X), input.BasicId, input, ct)</code>：</p><ul><li>新建：只读字段不能填写（与入参类型默认值相同视为没填，空串与 null 同义）</li><li>修改：只读字段改了值即拒绝；表单把拿到的<strong>脱敏值或空值原样交回</strong>视为没改，并<strong>还原成库里的原值</strong>——整体保存不会让 <code>138****5678</code> 覆盖真实号码</li><li>只写字段：交回脱敏值视为没改，填了新值照常保存</li></ul><p>没有只读或脱敏规则时不读库，零开销。同一请求内按「用户 + 实体」缓存解析结果，门控与打码共用一次查询。</p><p>个人中心改本人资料不经过字段安全（本人资料的读取也不打码）。</p><h2 id="写路径的租户边界" tabindex="-1">写路径的租户边界 <a class="header-anchor" href="#写路径的租户边界" aria-label="Permalink to &quot;写路径的租户边界&quot;">​</a></h2><p>除了行级与列级，还有一条容易忽略的边界：<strong>读共享 ≠ 写共享</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读：全局过滤器放行 TenantId IN (0, 当前租户)   ← 租户能读到平台全局数据；平台只读 0</span></span>
<span class="line"><span>写：只能改写/删除当前作用域的行               ← 租户不能改全局行，平台也不能改租户行</span></span></code></pre></div><p>实现方式：预读守卫校验取回行的 <code>TenantId</code>，条件写自动追加当前作用域的 <code>Where</code>。</p><p>平台就是 0 号租户：全局数据在平台作用域维护，某个租户的数据切入该租户（<code>ICurrentTenant.Change(tenantId)</code>）维护；跨租户读取只能显式清过滤（<code>...IgnoreTenantAsync</code> / <code>.ClearTenantFilter()</code>）。</p><p><strong>账号域数据</strong>。账号、安全记录、个人设置、通知偏好、接口凭证、三方绑定、密码历史是严格隔离的账号域数据，<code>TenantId</code> 固定为注册地（平台账号为 0）；一个人可以同时是多个租户的成员，切进别的租户后这些行经全局过滤不可见。个人中心的这些数据因此一律按 <code>UserId</code> 跨租户读（仓储上的 <code>...IgnoreTenantAsync</code> 与按用户唯一键的读法）；新增经 <code>IAccountScope</code> 切回注册地写，更新自己已有的行用 <code>TenantWriteGuard.Suppress()</code> 包裹（只放宽更新与删除，契约是只写当前用户自己的行）。会话与登录日志属于运行数据，按发生时所在的租户切分。</p><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>查什么</th></tr></thead><tbody><tr><td>有权限但列表为空</td><td>用户部门归属对不对 → 角色数据范围设成了什么 → 闭包表是否完整</td></tr><tr><td>某些行改不动</td><td>是否跨租户写（读得到不等于写得动）</td></tr><tr><td>列变成 null / 空</td><td>字段安全规则为「隐藏」，服务端已把值置空</td></tr><tr><td>列显示成 <code>***</code></td><td>字段安全的脱敏方式生效，服务端已打码</td></tr><tr><td>排序 / 搜索不生效</td><td>该字段读受保护，被剔出查询条件</td></tr><tr><td>改了数据范围不生效</td><td>该列表是否接了数据范围过滤；成员是否有覆盖（有覆盖时角色的范围不再生效）；角色是否停用、档位是否为自定义</td></tr><tr><td>配了规则不生效</td><td>实体、字段在规则列表里标「已失效」（代码已移除）；规则是否启用；目标是否命中（角色或部门停用、成员关系失效）</td></tr><tr><td>保存时报「无修改权限」</td><td>当前用户对该字段只读，改动了它的值</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./permission">权限管理</a>：权限码、RBAC 继承、ABAC、判定链</li><li><a href="./organization">组织架构</a>：部门树与闭包表</li><li><a href="./multi-tenancy">多租户 SaaS</a>：租户隔离与写路径边界</li><li><a href="./../frontend/permission">前端手册 · 权限与脱敏</a>：前端侧怎么接</li></ul>`,53)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
